<div class="art bg-base-300 text-base-content" aria-hidden="true">
 <div class="paper bg-base-100 text-base-content"><p class="botanical-eyebrow">Word play / 001</p><div class="letters">{#each 'PLAYIDEACLUEWORD'.split('') as letter, i}<span class:highlight={i % 5 === 0}>{letter}</span>{/each}</div><small>Find your next little discovery.</small></div>
 <div class="sticker bg-accent text-accent-content"><strong>5 min</strong><small>for a fresh idea</small></div>
</div>
<style>.art { height: 370px; position: relative; display: grid; place-items: center; border-radius: 180px 180px 24px 24px; } .paper { width: 265px; padding: 24px; border-radius: 20px; transform: rotate(3deg); box-shadow: 0 14px 30px #364b3e15; } .letters { display: grid; grid-template-columns: repeat(4,1fr); gap: 6px; margin: 18px 0; } .letters span { aspect-ratio: 1; display: grid; place-items: center; border-radius: 50%; background: var(--color-base-200); font-size: 22px; } .letters .highlight { background: var(--color-primary); color: var(--color-primary-content); } small { font-size: 10px; } .sticker { position: absolute; right: 14px; bottom: 22px; width: 100px; height: 100px; border-radius: 60% 40% 55% 45%; display: flex; flex-direction: column; align-items: center; justify-content: center; transform: rotate(-10deg); } strong { font-size: 23px; } @media(max-width:550px) { .art { height: 330px; } }</style>
